    "question": "What makes a dashboard worth using?",
    "is_question": true,
    "form": "Rafael’s analysis memo: The question, The data, What I did, What I found, What I would do.",
    "object": "One seven-leaf analysis memo comprising five section pages, a Lisbon Rent Map exhibit and Beatriz’s recommendation.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The structure uses Rafael’s supplied memo headings and connects his specific sample-tracking work, weekly report, public rent map and recommendation."
    },
    "backdrop": {
      "result": "fail",
      "reason": "The leaves mostly rearrange and frame information already explained by the page; removing their depth and motion loses visual choreography rather than an explanatory relationship."
    },
    "depth": {
      "result": "pass",
      "reason": "The journey develops an opening question through evidence, contributions and outcomes into a supported answer and contact invitation."
    },
    "clipart": {
      "result": "pass",
      "reason": "The memo is a confirmed working document with meaningful sections and exhibits, rather than a stock emblem of analytics."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan respects the corrected contributions, approximate results, project limitations, team credit and confidentiality restrictions."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen supplies Rafael’s name, role, positioning and reporting-time proof, with a persistent contact shortcut."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening uses straightforward language about dashboards people use and a concrete five-to-two-hour reporting improvement."
    }
  },
